using Real = double;

// P(x) is constant in intervals [b_i, b_{i+1})
std::vector<Real> boundaries = {0.0, 1.0, 2.0};
std::vector<Real> weights = {1.0, 3.0}; // Unnormalized densities

// UnaryOperation (e.g., a lambda) becomes part of the template signature
auto density_normalizer = [](Real d) { return d / 4.0; };

// Template Instantiation during compilation (Monomorphization)
using FunctorType = decltype(density_normalizer);

// Unique type generated by the compiler:
// std::piecewise_constant_distribution<double, UniqueLambdaType>
using SpecializedDist =
    std::piecewise_constant_distribution<Real, FunctorType>;

SpecializedDist distribution(
    boundaries.begin(), boundaries.end(),
    weights.begin(), density_normalizer
);

// Note: If density_normalizer were replaced by std::identity,
// a different, uniquely compiled SpecializedDist type results.
